import{_ as t,o,c as a,a3 as i}from"./chunks/framework.DACwFHq9.js";const m=JSON.parse(`{"title":"AI & MCP Capabilities","description":"Overview of Notely's Model Context Protocol (MCP) server, external AI integration, local ONNX embeddings, and Knowledge Graph capabilities.","frontmatter":{"title":"AI & MCP Capabilities","description":"Overview of Notely's Model Context Protocol (MCP) server, external AI integration, local ONNX embeddings, and Knowledge Graph capabilities.","keywords":"AI features, MCP, Model Context Protocol, Claude Desktop, Cursor, Antigravity, knowledge graph, vector embeddings, diagnostics","category":"AI"},"headers":[],"relativePath":"ai/features.md","filePath":"ai/features.md","lastUpdated":1789752683000}`),r={name:"ai/features.md"};function n(s,e,l,d,c,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-mcp-capabilities" tabindex="-1">AI &amp; MCP Capabilities <a class="header-anchor" href="#ai-mcp-capabilities" aria-label="Permalink to &quot;AI &amp; MCP Capabilities&quot;">​</a></h1><p>Notely adopts a privacy-first, local-centric AI architecture. Rather than relying on intrusive in-editor generative sidebars, conversational interaction is driven by an embedded <strong>Model Context Protocol (MCP)</strong> server, while local background workers handle semantic search embeddings and knowledge graph relation discovery.</p><hr><h2 id="_1-external-ai-integration-via-model-context-protocol-mcp" tabindex="-1">1. External AI Integration via Model Context Protocol (MCP) <a class="header-anchor" href="#_1-external-ai-integration-via-model-context-protocol-mcp" aria-label="Permalink to &quot;1. External AI Integration via Model Context Protocol (MCP)&quot;">​</a></h2><p>Notely embeds a dual-transport <strong>Model Context Protocol (MCP)</strong> server running on port <code>3700</code> (<code>http://127.0.0.1:3700/mcp</code> and <code>/sse</code>). This allows external LLM agents and desktop AI clients (such as Google Antigravity, Claude Desktop, Cursor, and IDE extensions) to interact directly with your notes, tasks, and diagrams.</p><h3 id="_7-enterprise-unified-tools" tabindex="-1">7 Enterprise Unified Tools <a class="header-anchor" href="#_7-enterprise-unified-tools" aria-label="Permalink to &quot;7 Enterprise Unified Tools&quot;">​</a></h3><p>External AI assistants have access to self-contained, structured tools:</p><ol><li><strong><code>search</code></strong>: Semantic hybrid search (FTS5 + BGE dense vector cosine similarity).</li><li><strong><code>read_note</code></strong>: Read note content, frontmatter, backlinks, and git revision history.</li><li><strong><code>edit_note</code></strong>: Create, overwrite, or surgical chunk-replace note text with atomic write safety.</li><li><strong><code>manage_tasks</code></strong>: Aggregate open/completed tasks, toggle status, and append checklist items.</li><li><strong><code>manage_diagrams</code></strong>: Read, create, and modify Mermaid, Draw.io, and Excalidraw diagrams.</li><li><strong><code>workspace_overview</code></strong>: Inspect file trees, broken link integrity, graph relations, and disk storage stats.</li><li><strong><code>git_control</code></strong>: Review stage status, commit diffs, commit history, and branches.</li></ol><h3 id="standard-mcp-prompts" tabindex="-1">Standard MCP Prompts <a class="header-anchor" href="#standard-mcp-prompts" aria-label="Permalink to &quot;Standard MCP Prompts&quot;">​</a></h3><p>Exposes ready-to-run interactive workflows to MCP clients:</p><ul><li><code>summarize_note</code>: Generate executive summaries from note contents.</li><li><code>plan_tasks</code>: Extract action items and checklists from freeform notes.</li><li><code>explore_knowledge_graph</code>: Traverse semantic relationships around specific concepts.</li><li><code>refactor_note</code>: Clean up structure, formatting, and heading hierarchy.</li><li><code>daily_review</code>: Synthesize recently modified notes and pending workspace tasks.</li></ul><p>For full schema details and client configuration, see the <a href="/mcp-tools-reference.html">Enterprise MCP Tools Reference</a> and <a href="/developer/mcp.html">Developer MCP Guide</a>.</p><hr><h2 id="_2-local-first-vector-embeddings" tabindex="-1">2. Local-First Vector Embeddings <a class="header-anchor" href="#_2-local-first-vector-embeddings" aria-label="Permalink to &quot;2. Local-First Vector Embeddings&quot;">​</a></h2><p>Notely indexes your workspace into <code>{workspace}/.notes-app/ai-embeddings.db</code>:</p><ul><li><strong>Local BGE Model</strong>: Uses <code>BGE-small-en-v1.5</code> (~130MB) executed on-device via <code>onnxruntime-node</code>.</li><li><strong>Hybrid Semantic Search</strong>: Combines full-text search (SQLite FTS5) with 384-dimensional dense vector embeddings for semantic similarity queries.</li><li><strong>Background Utility Process</strong>: Document chunking and vector calculations run in a dedicated background worker to keep the editor UI fast and stutter-free.</li></ul><hr><h2 id="_3-knowledge-graph-engine" tabindex="-1">3. Knowledge Graph Engine <a class="header-anchor" href="#_3-knowledge-graph-engine" aria-label="Permalink to &quot;3. Knowledge Graph Engine&quot;">​</a></h2><p>Notely features an offline, 8-stage Knowledge Graph engine mapped into <code>{workspace}/.notes-app/ai-graph.db</code>:</p><ul><li><strong>Neural Zero-Shot Extraction</strong>: Powered by an offline <code>gliner2-multi-v1-onnx</code> neural model running locally.</li><li><strong>Concept Deduplication &amp; Alias Fusion</strong>: Automatically merges variations of the same concept (e.g. &quot;SQLite DB&quot; and &quot;SQLite Database&quot;) using cosine vector similarity (&gt;0.88 threshold).</li><li><strong>Interactive Visualization</strong>: Explore entity clusters, backlinks, tags, and document references interactively from <strong>Workspace → Workspace Graph</strong> (<code>Ctrl/Cmd + Shift + G</code>).</li></ul><hr><h2 id="_4-mcp-tools-catalog-diagnostics" tabindex="-1">4. MCP Tools Catalog &amp; Diagnostics <a class="header-anchor" href="#_4-mcp-tools-catalog-diagnostics" aria-label="Permalink to &quot;4. MCP Tools Catalog &amp; Diagnostics&quot;">​</a></h2><p>Inspect and test AI operations inside the app:</p><ul><li><strong>MCP Tools Catalog</strong> (<code>Ctrl/Cmd + Shift + M</code>): View all registered MCP tools, test tool execution live with custom arguments, and inspect JSON responses.</li><li><strong>MCP Diagnostics &amp; Telemetry</strong>: Accessible from the Diagnostics panel, this dashboard displays live connection status, active client sessions, request rates, execution latency, and error logs.</li><li><strong>AI Settings</strong> (<code>Ctrl/Cmd + Shift + ,</code>): Configure LLM provider API keys (Gemini, Groq, OpenAI), embedding engine mode, and Knowledge Graph confidence thresholds.</li></ul>',24)])])}const h=t(r,[["render",n]]);export{m as __pageData,h as default};
